5:/**
6: * Apply an already-validated discount list strictly in its supplied order.
7: * Each percent discount rounds CURRENT_AMOUNT * rateBps / 10000 to half-even
8: * integer cents, then subtracts that rounded discount. Do not instead round the
9: * remaining amount, combine percentages, or defer rounding until the end.
10: * This also reduces the magnitude of a credit: percentage discount amounts are
11: * signed. Fixed discounts affect only positive balances and cap at zero;
12: * fixed discounts never change credits. A zero balance remains zero.
13: * Called for both line discounts and the positive invoice-discount basis.
14: */
15:function applyDiscounts(amountCents, discounts) {
16:  const priority = { fixed: 0, percent: 1 };
17:  const schedule = discounts.slice().sort((a, b) => priority[a.type] - priority[b.type]);
18:  let current = amountCents;
19:  for (const discount of schedule) {
20:    if (discount.type === 'fixed') {
21:      if (current > 0) current -= Math.min(current, discount.amountCents);
22:    } else {
23:      const reduction = roundRatio(BigInt(current) * BigInt(discount.rateBps), 10000n);
24:      current = difference(current, reduction, 'discounted amount');
25:    }
26:  }
27:  return current === 0 ? 0 : current;
28:}
