8:/**
9: * buildInvoice(input) -> a new invoice breakdown. See parse.js for the input
10: * schema, discounts.js for sequential discounts, rounding.js for exact half-even
11: * cents, allocation.js for remainder/tie rules, and tax.js for both tax modes.
12: *
13: * Pipeline: multiply unitCents by quantity; apply each line's discount list;
14: * compute the invoice discount against the SUM OF POSITIVE remaining balances
15: * (only when invoice discounts are present); apply the invoice discount list
16: * to that basis; allocate the resulting aggregate reduction ONCE across those
17: * positive balances; compute tax. Credits are excluded from invoice discounts
18: * but still contribute to all signed totals and their tax-rate group.
19: *
20: * Output lines preserve input order and contain currency, unitCents, quantity,
21: * grossCents, discountCents, netCents, taxBps, taxCents, totalCents. The returned
22: * invoice contains currency, taxMode, lines, subtotalCents (sum of gross),
23: * discountCents (sum of signed gross - net, including both discount levels),
24: * netCents, taxCents and totalCents. Each total equals the sum of corresponding
25: * line values. For credits discountCents may be negative. Empty invoices return
26: * zero totals and no lines. Nothing is mutated and returned zero amounts are +0.
27: *
28: * All input amounts and stored calculated fields are safe integer Numbers;
29: * exact arithmetic must precede safe-range checks. Reject unsafe line products,
30: * discount bases, calculated fields or totals with RangeError, never silently
31: * round an overflowing value. Intermediate products/sums may exceed the safe
32: * range provided the stored final result is safe (e.g. cancelling credits).
33: */
34:function buildInvoice(input) {
35:  const parsed = parseInvoice(input);
36:  const prepared = parsed.lines.map(line => {
37:    const grossCents = product(line.unitCents, line.quantity, 'line gross');
38:    return { ...line, grossCents, netCents: applyDiscounts(grossCents, line.discounts) };
39:  });
40:  const weights = prepared.map(line => Math.max(0, line.netCents));
41:  let invoiceReduction = 0;
42:  if (parsed.discounts.length > 0) {
43:    const basis = sum(weights, 'invoice discount basis');
44:    invoiceReduction = difference(basis, applyDiscounts(basis, parsed.discounts));
45:  }
46:  const shares = allocateDiscount(invoiceReduction, weights);
47:  prepared.forEach((line, index) => { line.netCents = difference(line.netCents, shares[index]); });
48:  const taxes = calculateTaxes(prepared, parsed.taxMode);
49:  const lines = prepared.map((line, index) => ({
50:    currency: line.currency,
51:    unitCents: line.unitCents,
52:    quantity: line.quantity,
53:    grossCents: line.grossCents,
54:    discountCents: difference(line.grossCents, line.netCents),
55:    netCents: line.netCents,
56:    taxBps: line.taxBps,
57:    taxCents: taxes[index],
58:    totalCents: sum([line.netCents, taxes[index]], 'line total'),
59:  }));
60:  const subtotalCents = sum(lines.map(line => line.grossCents), 'subtotal');
61:  const netCents = sum(lines.map(line => line.netCents), 'net total');
62:  const taxCents = sum(taxes, 'tax total');
